import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.countries().listCountries(Map.of("search", "aus"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("countries")) {
    Map<?, ?> country = (Map<?, ?>) row;
    System.out.println(country.get("id") + " " + country.get("code") + " " + country.get("name") + " " + country.get("state_count"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

